### src/decision/relay-decision-stage.js
```diff
--- /dev/null
+++ b/src/decision/relay-decision-stage.js
@@ -0,0 +1,180 @@
+const crypto = require('crypto');
+
+const FUND_FAMILY_KEYWORDS = [
+  'funds', 'disbursement', 'loan', 'refund money movement',
+  'signing', 'wallet', 'safe', 'credential access'
+];
+
+const VALID_DISPOSITIONS = [
+  'approve_in_scope',
+  'conditional_approve',
+  'return_for_revision',
+  'needs_decision'
+];
+
+const REQUIRED_FIELDS = {
+  'approve_in_scope': ['disposition', 'task_id', 'reasoning'],
+  'conditional_approve': ['disposition', 'task_id', 'reasoning', 'conditions'],
+  'return_for_revision': ['disposition', 'task_id', 'reasoning', 'required_changes'],
+  'needs_decision': ['disposition', 'task_id', 'reasoning', 'escalation_reason']
+};
+
+class RelayDecisionStage {
+  constructor(config) {
+    this.proxyUrl = config.proxyUrl;
+    this.proxyToken = config.proxyToken;
+    this.allowlistedHosts = config.allowlistedHosts || [];
+    this.allowlistedModels = config.allowlistedModels || [];
+    this.timeoutMs = config.timeoutMs || 30000;
+    this.decisions = new Map();
+  }
+
+  isFundFamilyItem(taskDescription) {
+    const lowerDesc = taskDescription.toLowerCase();
+    return FUND_FAMILY_KEYWORDS.some(keyword => lowerDesc.includes(keyword));
+  }
+
+  async makeDecision(taskId, inputData, inputSha256) {
+    // Hard fail-closed: missing acceptance gate
+    if (!this.proxyToken) {
+      return { status: 'undecided', reason: 'missing_proxy_token' };
+    }
+
+    // Fund-family short circuit
+    if (this.isFundFamilyItem(inputData.description || '')) {
+      return {
+        status: 'escalated',
+        disposition: 'needs_owner_decision',
+        reason: 'fund_family_item',
+        task_id: taskId
+      };
+    }
+
+    // Check for duplicate decision
+    if (this.decisions.has(taskId)) {
+      return { status: 'undecided', reason: 'duplicate_decision' };
+    }
+
+    // Prepare batch with required header
+    const batch = {
+      header: {
+        batch_type: 'decision_request',
+        task_id: taskId,
+        input_sha256: inputSha256,
+        timestamp: new Date().toISOString()
+      },
+      payload: inputData
+    };
+
+    try {
+      const response = await this._callRelay(batch);
+      
+      // Validate response structure
+      const validationResult = this._validateDecisionResponse(response, taskId, inputSha256);
+      
+      if (!validationResult.valid) {
+        return { status: 'undecided', reason: validationResult.reason };
+      }
+
+      // Extract metadata
+      const metadata = {
+        provider: response.metadata?.provider || 'unknown',
+        model: response.metadata?.model || 'unverified',
+        request_id: response.metadata?.request_id || null,
+        relay_attested: response.metadata?.attested === true
+      };
+
+      // Mark relay_attested = false when upstream attestation unavailable
+      if (!response.metadata?.attested) {
+        metadata.relay_attested = false;
+      }
+
+      // Validate host and model allowlists
+      if (this.allowlistedHosts.length > 0 && 
+          !this.allowlistedHosts.includes(metadata.provider)) {
+        return { status: 'undecided', reason: 'host_not_allowlisted' };
+      }
+
+      if (this.allowlistedModels.length > 0 && 
+          !this.allowlistedModels.includes(metadata.model)) {
+        return { status: 'undecided', reason: 'model_not_allowlisted' };
+      }
+
+      const decision = {
+        ...response.decision,
+        task_id: taskId,
+        input_sha256: inputSha256,
+        metadata,
+        decided_at: new Date().toISOString(),
+        production_authorized: false,
+        funds_authorized: false
+      };
+
+      this.decisions.set(taskId, decision);
+      return { status: 'decided', decision };
+
+    } catch (error) {
+      if (error.name === 'TimeoutError') {
+        return { status: 'undecided', reason: 'timeout_no_retry' };
+      }
+      return { status: 'undecided', reason: 'unknown_delivery' };
+    }
+  }
+
+  async _callRelay(batch) {
+    const controller = new AbortController();
+    const timeoutId = setTimeout(() => controller.abort(), this.timeoutMs);
+
+    try {
+      const response = await fetch(this.proxyUrl, {
+        method: 'POST',
+        headers: {
+          'Content-Type': 'application/json',
+          'Authorization': `Bearer ${this.proxyToken}`
+        },
+        body: JSON.stringify(batch),
+        signal: controller.signal
+      });
+
+      clearTimeout(timeoutId);
+
+      if (!response.ok) {
+        throw new Error(`Relay returned ${response.status}`);
+      }
+
+      return await response.json();
+    } catch (error) {
+      clearTimeout(timeoutId);
+      if (error.name === 'AbortError') {
+        const timeoutError = new Error('Request timeout');
+        timeoutError.name = 'TimeoutError';
+        throw timeoutError;
+      }
+      throw error;
+    }
+  }
+
+  _validateDecisionResponse(response, expectedTaskId, expectedSha256) {
+    // Missing batch header
+    if (!response.header) {
+      return { valid: false, reason: 'missing_batch_header' };
+    }
+
+    // Non-JSON or malformed
+    if (!response.decision || typeof response.decision !== 'object') {
+      return { valid: false, reason: 'malformed_json' };
+    }
+
+    const { decision } = response;
+
+    // Unknown disposition
+    if (!VALID_DISPOSITIONS.includes(decision.disposition)) {
+      return { valid: false, reason: 'non_json_or_malformed' };
+    }
+
+    // Task ID mismatch
+    if (decision.task_id !== expectedTaskId) {
+      return { valid: false, reason: 'wrong_task_id' };
+    }
+
+    // Hash mismatch
+    if (response.header.input_sha256 !== expectedSha256) {
+      return { valid: false, reason: 'hash_mismatch' };
+    }
+
+    // Required fields per disposition
+    const requiredFields = REQUIRED_FIELDS[decision.disposition];
+    for (const field of requiredFields) {
+      if (!(field in decision)) {
+        return { valid: false, reason: 'non_json_or_malformed' };
+      }
+    }
+
+    return { valid: true };
+  }
+}
+
+module.exports = RelayDecisionStage;
```

