  "required": ["header", "decision", "metadata"],
  "properties": {
    "header": {
      "type": "object",
      "required": ["batch_type", "task_id", "input_sha256"],
      "properties": {
        "batch_type": { "type": "string", "const": "decision_response" },
        "task_id": { "type": "string" },
