const RelayDecisionStage = require('../../src/decision/relay-decision-stage');
const crypto = require('crypto');

describe('RelayDecisionStage', () => {
  let stage;
  let mockFetch;

  beforeEach(() => {
    mockFetch = jest.fn();
    global.fetch = mockFetch;

    stage = new RelayDecisionStage({
      proxyUrl: 'https://relay.example.com/decide',
      proxyToken: 'test-token-123',
      allowlistedHosts: ['relay.example.com'],
      allowlistedModels: ['gpt-4'],
      timeoutMs: 5000
