    const taskId = 'task-001';
    const inputSha = crypto.createHash('sha256').update('test input').digest('hex');

    mockFetch.mockResolvedValue({
      ok: true,
      json: async () => ({
        header: { batch_type: 'decision_response', task_id: taskId, input_sha256: inputSha },
        decision: { disposition: 'approve_in_scope', task_id: taskId, reasoning: 'Safe to proceed' },
