const { isFundFamilyItem } = require('../../src/decision/fund-family-predicate');
const RelayDecisionStage = require('../../src/decision/relay-decision-stage');

describe('Fund-family short circuit', () => {
  test('detects funds keyword', () => {
    expect(isFundFamilyItem('transfer funds to account')).toBe(true);
  });

  test('detects disbursement keyword', () => {
    expect(isFundFamilyItem('process disbursement request')).toBe(true);
  });

  test('detects loan keyword', () => {
    expect(isFundFamilyItem('approve loan application')).toBe(true);
  });

  test('detects refund money movement keyword', () => {
    expect(isFundFamilyItem('initiate refund money movement')).toBe(true);
  });

  test('detects signing keyword', () => {
    expect(isFundFamilyItem('perform transaction signing')).toBe(true);
  });

  test('detects wallet keyword', () => {
    expect(isFundFamilyItem('access wallet balance')).toBe(true);
  });

  test('detects safe keyword', () => {
    expect(isFundFamilyItem('open safe for withdrawal')).toBe(true);
  });

  test('detects credential access keyword', () => {
    expect(isFundFamilyItem('retrieve credential access token')).toBe(true);
  });

  test('allows non-fund tasks', () => {
    expect(isFundFamilyItem('update documentation')).toBe(false);
    expect(isFundFamilyItem('run tests')).toBe(false);
  });

  test('short circuits fund-family BEFORE relay call', async () => {
    const mockFetch = jest.fn();
    global.fetch = mockFetch;

    const stage = new RelayDecisionStage({
      proxyUrl: 'https://relay.example.com/decide',
      proxyToken: 'test-token'
    });

    const result = await stage.makeDecision(
      'task-fund-001',
      { description: 'transfer funds to external account' },
      'dummyhash'
    );

    expect(result.status).toBe('escalated');
    expect(result.disposition).toBe('needs_owner_decision');
    expect(result.reason).toBe('fund_family_item');
    expect(mockFetch).not.toHaveBeenCalled();
  });
});
