### .github/workflows/deploy-decision-stage.yml
```yaml
name: Deploy Decision Stage

on:
  push:
    branches: [main]
  workflow_dispatch:

jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - run: npm ci
      - run: npm test
        id: test_run
      - name: Check test results
        if: failure()
        run: |
          echo "Tests failed - deployment blocked"
          exit 1

  deploy:
    needs: test
    runs-on: ubuntu-latest
    environment: production
    steps:
      - uses: actions/checkout@v3

      - name: Deploy to runtime
        id: deploy
        env:
          DEPLOY_TOKEN: ${{ secrets.DEPLOY_TOKEN }}
          RUNTIME_URL: ${{ secrets.RUNTIME_URL }}
        run: |
          COMMIT_SHA=$(git rev-parse HEAD)
          echo "commit_sha=$COMMIT_SHA" >> $GITHUB_OUTPUT

          RESPONSE=$(curl -s -w "\n%{http_code}" -X POST "$RUNTIME_URL/deploy" \
            -H "Authorization: Bearer $DEPLOY_TOKEN" \
            -H "Content-Type: application/json" \
            -d "{\"commit\":\"$COMMIT_SHA\",\"component\":\"decision-stage\"}")

          HTTP_CODE=$(echo "$RESPONSE" | tail -n1)
          BODY=$(echo "$RESPONSE" | head -n-1)

          echo "http_code=$HTTP_CODE" >> $GITHUB_OUTPUT
          echo "response_body=$BODY" >> $GITHUB_OUTPUT

          if [ "$HTTP_CODE" != "200" ]; then
            echo "Deploy failed with HTTP $HTTP_CODE"
            exit 1
          fi

          VERSION=$(echo "$BODY" | jq -r '.deployed_version')
          echo "deployed_version=$VERSION" >> $GITHUB_OUTPUT

      - name: Verify deployment
        id: verify
        env:
          RUNTIME_URL: ${{ secrets.RUNTIME_URL }}
        run: |
          sleep 10

          VERSION_RESPONSE=$(curl -s "$RUNTIME_URL/version")
          ACTIVE_VERSION=$(echo "$VERSION_RESPONSE" | jq -r '.decision_stage_version')

          echo "active_version=$ACTIVE_VERSION" >> $GITHUB_OUTPUT

          if [ "$ACTIVE_VERSION" != "${{ steps.deploy.outputs.deployed_version }}" ]; then
            echo "Version mismatch: expected ${{ steps.deploy.outputs.deployed_version }}, got $ACTIVE_VERSION"
            exit 1
          fi

      - name: Smoke test
        id: smoke
        env:
          RUNTIME_URL: ${{ secrets.RUNTIME_URL }}
          SMOKE_TOKEN: ${{ secrets.SMOKE_TOKEN }}
        run: |
          SMOKE_RESPONSE=$(curl -s -w "\n%{http_code}" -X POST "$RUNTIME_URL/decision/smoke" \
            -H "Authorization: Bearer $SMOKE_TOKEN" \
            -H "Content-Type: application/json" \
            -d '{"task_id":"smoke-test","description":"smoke test task"}')

          SMOKE_CODE=$(echo "$SMOKE_RESPONSE" | tail -n1)
          SMOKE_BODY=$(echo "$SMOKE_RESPONSE" | head -n-1)

          echo "smoke_code=$SMOKE_CODE" >> $GITHUB_OUTPUT
          echo "smoke_body=$SMOKE_BODY" >> $GITHUB_OUTPUT

          if [ "$SMOKE_CODE" = "200" ]; then
            echo "smoke_verified=true" >> $GITHUB_OUTPUT
            echo "SMOKE TEST PASSED"
          else
            echo "smoke_verified=false" >> $GITHUB_OUTPUT
            echo "DEPLOYED_BUT_NOT_SMOKE_VERIFIED"
          fi

      - name: Rollback on failure
        if: failure()
        env:
          DEPLOY_TOKEN: ${{ secrets.DEPLOY_TOKEN }}
          RUNTIME_URL: ${{ secrets.RUNTIME_URL }}
        run: |
          echo "Deployment failed - initiating rollback"
          curl -X POST "$RUNTIME_URL/rollback" \
            -H "Authorization: Bearer $DEPLOY_TOKEN" \
            -H "Content-Type: application/json" \
            -d '{"reason":"deployment_verification_failed"}'

      - name: Output summary
        run: |
          echo "## Deployment Summary" >> $GITHUB_STEP_SUMMARY
          echo "- Run ID: ${{ github.run_id }}" >> $GITHUB_STEP_SUMMARY
          echo "- Job: ${{ github.job }}" >> $GITHUB_STEP_SUMMARY
          echo "- Commit: ${{ steps.deploy.outputs.commit_sha }}" >> $GITHUB_STEP_SUMMARY
          echo "- Deployed Version: ${{ steps.deploy.outputs.deployed_version }}" >> $GITHUB_STEP_SUMMARY
          echo "- Active Version: ${{ steps.verify.outputs.active_version }}" >> $GITHUB_STEP_SUMMARY
          echo "- Smoke Verified: ${{ steps.smoke.outputs.smoke_verified }}" >> $GITHUB_STEP_SUMMARY
```

**PASS Criteria:**
1. All tests green (npm test exit 0)
2. HTTP 200 from deploy endpoint
3. Version readback matches deployed version
4. Smoke test returns 200 OR explicitly marked DEPLOYED_BUT_NOT_SMOKE_VERIFIED

**Rollback:**
- Triggered on any step failure
- Calls /rollback endpoint
- Reverts to previous stable version
- Logs rollback reason

